package com.bank.iface;

import java.math.BigDecimal;
import java.util.logging.Logger;

public interface PaymentProcessor {
    // Implicitly public static final constant — the pre-Java 8 capability.
    BigDecimal AUDIT_FEE = new BigDecimal("10.00");

    // ORIGINAL abstract method (pre-Java 8 style): every implementer must provide it.
    void process(Account from, Account to, BigDecimal amount);

    // JAVA 8 DEFAULT METHOD: new capability added WITHOUT breaking old implementers.
    // Existing classes inherit this body automatically and keep compiling.
    default void transferWithAudit(Account from, Account to, BigDecimal amount) {
        Logger log = Logger.getLogger(PaymentProcessor.class.getName());
        BigDecimal total = withFee(amount);          // calls the Java 9 private helper
        process(from, to, amount);                    // reuse the existing contract
        log.info(() -> "Audited transfer " + amount + " (fee " + AUDIT_FEE + ", total "
                + total + ") from " + from.getAccountId() + " to " + to.getAccountId());
    }

    // JAVA 9 PRIVATE METHOD: shared helper hidden from implementers, used by the
    // default method above and the static factory below. Not part of public API.
    private BigDecimal withFee(BigDecimal amount) {
        return amount.add(AUDIT_FEE);
    }

    // JAVA 8 STATIC METHOD: factory on the interface itself, no utility class needed.
    static PaymentProcessor standard() {
        return new BasicProcessor();
    }
}
