package com.bank.iface;

import java.math.BigDecimal;
import java.util.logging.Logger;

// An OLD implementer written before transferWithAudit existed. It implements only
// the original process() method and does NOT override the default. It still gains
// the new transferWithAudit capability for free — this is backward-compatible evolution.
public class BasicProcessor implements PaymentProcessor {
    private static final Logger log = Logger.getLogger(BasicProcessor.class.getName());

    @Override
    public void process(Account from, Account to, BigDecimal amount) {
        from.debit(amount);
        to.credit(amount);
        log.info(() -> "Processed " + amount + " from " + from.getAccountId()
                + " to " + to.getAccountId());
    }
}
