package com.bank.iface;

import java.math.BigDecimal;
import java.util.logging.*;

public class InterfaceEvolutionDemo {
    private static final Logger log = Logger.getLogger(InterfaceEvolutionDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setLevel(Level.ALL);
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Account rajesh = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000"));
        Account priya  = new Account("CUR3001", "Priya Sharma", new BigDecimal("250000"));

        // Java 8 static factory on the interface builds a ready-made processor.
        PaymentProcessor processor = PaymentProcessor.standard();

        BigDecimal rentAmount = new BigDecimal("50000");
        // The OLD BasicProcessor never defined transferWithAudit, yet it works,
        // because it inherited the Java 8 default method automatically.
        processor.transferWithAudit(rajesh, priya, rentAmount);

        log.info(() -> "Rajesh=" + rajesh.getBalance() + " Priya=" + priya.getBalance());
        log.info(() -> "Interface constant AUDIT_FEE (pre-Java 8 style) = " + PaymentProcessor.AUDIT_FEE);
    }
}
